<?php
declare(strict_types=1);require_once __DIR__ . '/config/product_step11.php';$error=null;$all=[];$selected=[];$ids=[];foreach(explode(',',(string)($_GET['ids']??'')) as $v)if(is_numeric($v)&&count($ids)<4)$ids[]=(int)$v;try{$pdo=business_db();product_step11_ensure($pdo);$ctx=product_org_context($pdo);$orgId=(int)$ctx['organization_id'];$all=product_step11_catalog_rows($pdo,$orgId);foreach($all as $r)if(in_array((int)$r['id'],$ids,true))$selected[]=$r;}catch(Throwable $e){$error=$e->getMessage();}?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Product Compare - Healthcare Wellness Club</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/product_pro.css"></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="product_catalog.php"><img src="../img/logo.png" alt="logo"><span><strong>Healthcare Wellness Club</strong><small>Product & Price Pro • Compare</small></span></a><div class="os-top-actions"><a class="os-btn" href="product_catalog.php">Catalog</a><a class="os-btn primary" href="product_order_builder.php">Order Builder</a></div></div></header><div class="os-layout"><aside class="os-sidebar"><div class="os-nav-label">Product System</div><nav class="os-nav"><a href="product_catalog.php"><i class="dot"></i>Catalog</a><a class="active" href="product_compare.php"><i class="dot"></i>Compare</a><a href="product_order_builder.php"><i class="dot"></i>Order Builder</a><a href="product_price_history.php"><i class="dot"></i>Price History</a></nav></aside><main class="os-main"><section class="os-hero pp-hero"><div class="os-kicker">STEP 11 • Product Comparison</div><h1>Compare MRP, VP and every available customer/associate price side by side.</h1><p>Select up to four products. Missing tiers remain blank rather than being guessed.</p></section><?php if($error):?><div class="pp-alert bad"><?= product_h($error) ?></div><?php else:?><section class="os-card" style="margin-top:14px"><form method="get" class="pp-form"><label>Select up to 4 products<select name="ids[]" multiple size="10"><?php foreach($all as $r):?><option value="<?= (int)$r['id'] ?>" <?= in_array((int)$r['id'],$ids,true)?'selected':'' ?>><?= product_h($r['sku'].' - '.$r['product_name']) ?></option><?php endforeach;?></select></label><small style="color:#73847b">Desktop: Ctrl/Cmd-click to select multiple products.</small><button>Compare Selected</button></form></section><?php if($selected):?><section class="os-card" style="margin-top:14px"><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>Field</th><?php foreach($selected as $r):?><th><?= product_h($r['sku']) ?><br><?= product_h($r['product_name']) ?></th><?php endforeach;?></tr></thead><tbody><?php $fields=['MRP'=>'MRP','PC_BRONZE'=>'Preferred Bronze','PC_SILVER'=>'Preferred Silver','PC_GOLD'=>'Preferred Gold','ASSOC_RETAIL'=>'Associate Retail','ASSOC_EARN_BASE'=>'Earn Base','ASSOC_25'=>'25%','ASSOC_35'=>'35%','ASSOC_42'=>'42%','ASSOC_50'=>'50%','PU_PRICE'=>'PU Price'];?><tr><td><b>Volume Points</b></td><?php foreach($selected as $r):?><td><?= product_h(rtrim(rtrim(number_format((float)$r['volume_points'],3,'.',''),'0'),'.')) ?></td><?php endforeach;?></tr><?php foreach($fields as $code=>$label):?><tr><td><b><?= product_h($label) ?></b></td><?php foreach($selected as $r):$v=$code==='MRP'?(float)$r['mrp']:($r['tiers'][$code]??null);?><td><?= $v===null?'—':'₹'.number_format((float)$v,2) ?></td><?php endforeach;?></tr><?php endforeach;?></tbody></table></div></section><?php endif;?><?php endif;?></main></div></body></html>